mapper.insert:
insert into source.source_entity (
    id, name, slug, entity_type, country_code, official_level, authority_score,
    website_url, logo_url, status, version, created_by
) values (
    #{id}, #{name}, #{slug}, #{entityType}, #{countryCode}, #{officialLevel}, #{authorityScore},
    #{websiteUrl}, #{logoUrl}, #{status}, #{version}, #{createdBy}
)

insert into source.source_endpoint (
    id, source_entity_id, name, url, normalized_url, endpoint_type, connector_type,
    language, polling_interval_seconds, display_policy, index_policy, authority_override,
    config, credential_ref, status, health_status, failure_count, version, created_by
) values (
    #{id}, #{sourceEntityId}, #{name}, #{url}, #{normalizedUrl}, #{endpointType}, #{connectorType},
    #{language}, #{pollingIntervalSeconds}, #{displayPolicy}, #{indexPolicy}, #{authorityOverride},
    cast(#{configJson} as jsonb), #{credentialRef}, #{status}, #{healthStatus}, #{failureCount}, #{version}, #{createdBy}
)

mapper.select:
select id, name, slug, entity_type, country_code, official_level, authority_score,
       website_url, logo_url, status, version, created_by, created_at, updated_at
from source.source_entity where id = #{id}

select s.id, s.name, s.slug, s.entity_type, s.official_level, s.authority_score, s.status as source_status, e.id as endpoint_id, e.name as endpoint_name, e.endpoint_type, e.url as endpoint_url, e.status as endpoint_status, e.health_status, e.last_success_at, e.last_failure_at, e.version as endpoint_version, e.updated_at from source.source_entity s join source.source_endpoint e on e.source_entity_id = s.id
e.status = #{status}
and (s.name ilike '%' || #{query} || '%' or e.name ilike '%' || #{query} || '%' or e.normalized_url ilike '%' || #{query} || '%')
order by e.updated_at desc, e.id desc limit #{limit}

mapper.update:
update source.source_endpoint
set status = #{status}, version = version + 1, updated_at = now()
where id = #{id} and version = #{version}
